'use strict';
(()=>{let draft={},image='',imageBusy=false;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(name,label,value='',extra='')=>`<label>${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;
function values(){const f=document.querySelector('#marketing-draft');if(!f)return draft;const d=Object.fromEntries(new FormData(f));return {...d,image,samples:[...f.querySelectorAll('[data-template-sample]')].map(x=>x.value),buttons:[0,1,2].map(i=>({type:d['buttonType'+i],text:d['buttonText'+i],url:d['buttonUrl'+i],phone_number:d['buttonPhone'+i]})).filter(b=>b.type&&b.type!=='NONE')};}
async function prepare(file){if(!file||!['image/png','image/jpeg'].includes(file.type)||file.size>5*1024*1024)throw Error('ارفع PNG أو JPG حتى 5 ميجابايت.');let url;try{url=URL.createObjectURL(file);const img=new Image();img.src=url;await img.decode();if(img.width*img.height>16000000)throw Error('اختر صورة أصغر من 16 مليون بكسل.');const ratio=Math.min(1,1200/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.85);if(data.length>1400000)throw Error('اختر صورة أخف.');return data;}finally{if(url)URL.revokeObjectURL(url);}}
function preview(d){const body=String(d.body||'نص الرسالة يظهر هنا').replace(/\{\{(\d+)\}\}/g,(_,i)=>d.samples?.[Number(i)-1]||'{{'+i+'}}');return `<div class="wa-device"><div class="wa-chat-header"><span class="wa-avatar">ر</span><div><strong>حساب نشاطك</strong><small>WhatsApp Business</small></div><span aria-hidden="true">⋮</span></div><div class="wa-chat"><span class="wa-day">اليوم</span><article class="wa-bubble">${d.headerType==='IMAGE'?d.image?`<img class="wa-media" src="${esc(d.image)}" alt="صورة القالب">`:'<div class="wa-media-empty">صورة الترويسة</div>':d.headerType==='TEXT'?`<b class="wa-heading">${esc(d.header||'عنوان الرسالة')}</b>`:''}<p class="wa-body">${esc(body)}</p>${d.footer?`<p class="wa-footer">${esc(d.footer)}</p>`:''}<span class="wa-time">الآن ✓✓</span>${(d.buttons||[]).map(b=>`<div class="wa-button">${b.type==='URL'?'↗':b.type==='PHONE_NUMBER'?'☎':'↩'} ${esc(b.text||'نص الزر')}</div>`).join('')}</article></div></div>`;}
function update(){const d=values(),p=document.querySelector('#marketing-preview');if(p)p.innerHTML=preview(d);const count=document.querySelector('#template-body-count');if(count)count.textContent=(d.body||'').length+' / 1024';document.querySelectorAll('[data-header-field]').forEach(el=>el.hidden=el.dataset.headerField!==d.headerType);for(let i=0;i<3;i++){const url=document.querySelector('[data-button-url="'+i+'"]'),phone=document.querySelector('[data-button-phone="'+i+'"]'),text=document.querySelector('[data-button-text="'+i+'"]');if(url)url.hidden=d['buttonType'+i]!=='URL';if(phone)phone.hidden=d['buttonType'+i]!=='PHONE_NUMBER';if(text)text.hidden=['NONE',''].includes(d['buttonType'+i]);}}
function samples(){const f=document.querySelector('#marketing-draft'),box=document.querySelector('#template-samples');if(!f||!box)return;const used=[...new Set([...f.elements.body.value.matchAll(/\{\{(\d+)\}\}/g)].map(x=>Number(x[1])))].sort((a,b)=>a-b).slice(0,5),existing=Object.fromEntries([...box.querySelectorAll('input')].map(x=>[x.dataset.templateSample,x.value]));if(box.dataset.used===used.join(','))return;box.dataset.used=used.join(',');box.innerHTML=used.map(i=>`<label>مثال المتغير {{${i}}}<input data-template-sample="${i}" value="${esc(existing[i]||draft.samples?.[i-1]||'')}" required maxlength="100" placeholder="مثال يعرض لميتا عند المراجعة"></label>`).join('');}
function editor(items){image=draft.image||'';return `<div class="template-workspace"><section class="marketing-panel template-editor"><div class="section-heading"><div><h2>${draft.id?'تعديل مسودة القالب':'إنشاء قالب واتساب'}</h2><p>نص وصورة وأزرار، مع معاينة مباشرة قبل الحفظ أو المراجعة.</p></div><span class="marketing-status">اعتماد ميتا مطلوب</span></div><div class="preset-row"><button type="button" class="info-button" data-template-preset="reward">مكافأة ولاء</button><button type="button" class="info-button" data-template-preset="offer">عرض مع رابط</button><button type="button" class="info-button" data-template-preset="reminder">تذكير</button></div><form id="marketing-draft"><input type="hidden" name="kind" value="template"><input type="hidden" name="id" value="${esc(draft.id||'')}"><div class="form-row">${field('title','اسم داخلي',draft.title,'required maxlength="100"')}${field('name','اسم القالب لدى ميتا',draft.name,'required pattern="[a-z0-9_]+" maxlength="80" dir="ltr" placeholder="rijaa_offer"')}</div><div class="form-row"><label>التصنيف<select name="category"><option value="MARKETING" ${draft.category!=='UTILITY'?'selected':''}>تسويق · عروض ومكافآت</option><option value="UTILITY" ${draft.category==='UTILITY'?'selected':''}>خدمي · مرتبط بطلب العميل</option></select></label>${field('language','اللغة',draft.language||'ar','required dir="ltr" maxlength="12"')}</div><label>استخدام القالب<select name="purpose"><option value="loyalty" ${draft.purpose!=='general'?'selected':''}>برامج الولاء</option><option value="general" ${draft.purpose==='general'?'selected':''}>عام · خارج بطاقات الولاء</option></select></label><fieldset><legend>الترويسة</legend><label>نوع الترويسة<select name="headerType">${[['NONE','بدون ترويسة'],['TEXT','عنوان نصي'],['IMAGE','صورة']].map(([v,t])=>`<option value="${v}" ${v===(draft.headerType||'NONE')?'selected':''}>${t}</option>`).join('')}</select></label><div data-header-field="TEXT">${field('header','العنوان',draft.header,'maxlength="60"')}</div><div data-header-field="IMAGE"><label class="image-upload">صورة الرسالة<input id="template-image" type="file" accept="image/png,image/jpeg"><small>PNG أو JPG حتى 5 ميجابايت؛ نهيئها تلقائيًا لعرض واتساب.</small></label><button type="button" class="info-button" data-template-remove-image>إزالة الصورة</button></div></fieldset><label>نص الرسالة<textarea name="body" required maxlength="1024" placeholder="مرحبًا {{1}}، مكافأتك تنتظرك">${esc(draft.body)}</textarea></label><div class="editor-counter"><button type="button" class="info-button" data-template-variable>إضافة متغير</button><small id="template-body-count"></small></div><div id="template-samples" class="form-row"></div>${field('footer','تذييل · اختياري',draft.footer,'maxlength="60" placeholder="نص قصير أسفل الرسالة"')}<fieldset><legend>أزرار الرسالة · اختياري</legend><p>حتى 3 ردود سريعة، أو رابطين وزر اتصال. الروابط ثابتة وتبدأ HTTPS.</p>${[0,1,2].map(i=>{const b=draft.buttons?.[i]||{};return `<div class="template-button-row"><label>الزر ${i+1}<select name="buttonType${i}">${[['NONE','بدون زر'],['URL','زيارة رابط'],['PHONE_NUMBER','اتصال'],['QUICK_REPLY','رد سريع']].map(([v,t])=>`<option value="${v}" ${v===(b.type||'NONE')?'selected':''}>${t}</option>`).join('')}</select></label><div data-button-text="${i}">${field('buttonText'+i,'نص الزر',b.text,'maxlength="25"')}</div><div data-button-url="${i}">${field('buttonUrl'+i,'الرابط',b.url,'type="url" dir="ltr" placeholder="https://…"')}</div><div data-button-phone="${i}">${field('buttonPhone'+i,'رقم الاتصال الدولي',b.phone_number,'dir="ltr" placeholder="+966…"')}</div></div>`;}).join('')}</fieldset><div class="marketing-actions"><button class="info-button gold">حفظ المسودة</button>${draft.id?'<button type="button" class="info-button" data-template-new>قالب جديد</button>':''}</div><p>الحفظ والمعاينة لا يرسلان رسائل. إرسال القالب لمراجعة ميتا خطوة مستقلة.</p></form></section><aside class="template-preview-panel"><div class="preview-title"><h2>معاينة واتساب</h2><small>النص والأزرار كما يراها المستلم</small></div><div id="marketing-preview">${preview(draft)}</div></aside></div><section class="marketing-panel"><div class="section-heading"><h2>قوالبك المحفوظة</h2><button class="info-button" type="button" data-marketing="sync">تحديث قوالب ميتا</button></div><div class="template-library">${items.map(d=>`<article class="template-library-card"><div><b>${esc(d.title)}</b><span class="marketing-status">${d.status==='submitted'?'أُرسل للمراجعة':'مسودة'}</span></div><small dir="ltr">${esc(d.name)} · ${esc(d.language)}</small><p>${esc(d.body)}</p><div class="marketing-actions"><button class="info-button" data-template-edit="${esc(d.id)}">معاينة${d.status==='submitted'?'':' وتعديل'}</button><button class="info-button gold" data-marketing="submit" data-id="${esc(d.id)}" ${d.status==='submitted'?'disabled':''}>إرسال للمراجعة</button></div></article>`).join('')||'<p>ابدأ بقالب من الاختصارات أعلاه.</p>'}</div></section>`;}
document.addEventListener('input',e=>{if(e.target.closest('#marketing-draft')&&document.querySelector('#template-samples')){samples();update();}});
document.addEventListener('change',async e=>{if(e.target.id!=='template-image')return;const file=e.target.files?.[0];if(!file)return;const say=t=>document.querySelector('#marketing-alert').textContent=t;if(!['image/png','image/jpeg'].includes(file.type)||file.size>5*1024*1024){say('ارفع PNG أو JPG حتى 5 ميجابايت.');return;}imageBusy=true;let url;try{url=URL.createObjectURL(file);const img=new Image();img.src=url;await img.decode();if(img.width*img.height>16000000)throw Error('الصورة كبيرة؛ استخدم مقاسًا أقل من 16 مليون بكسل.');const ratio=Math.min(1,1200/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);image=canvas.toDataURL('image/jpeg',.85);if(image.length>1400000)throw Error('الصورة كبيرة بعد المعالجة؛ اختر صورة أخف.');update();say('الصورة جاهزة للمعاينة؛ لم تُرسل إلى ميتا.');}catch(err){image='';say(err.message||'تعذر قراءة الصورة.');}finally{if(url)URL.revokeObjectURL(url);imageBusy=false;}});
document.addEventListener('click',e=>{if(e.target.closest('[data-template-remove-image]')){image='';update();}if(e.target.closest('[data-template-variable]')){const f=document.querySelector('#marketing-draft'),count=new Set([...f.elements.body.value.matchAll(/\{\{(\d+)\}\}/g)].map(x=>x[1])).size;if(count<5){f.elements.body.value+=' {{'+(count+1)+'}}';samples();update();}}});
window.MarketingTemplateEditor={prepare,preview,keep:()=>{if(draft.status!=='submitted')draft={...draft,...values()};},html:editor,init:()=>{samples();update();if(draft.status==='submitted')document.querySelectorAll('#marketing-draft input,#marketing-draft select,#marketing-draft textarea,#marketing-draft button:not([data-template-new])').forEach(x=>x.disabled=true);},read:()=>{if(imageBusy)throw Error('انتظر تجهيز الصورة.');return values();},load:d=>{draft={...d};},reset:()=>{draft={};image='';},preset:id=>{draft={language:'ar',category:'MARKETING',purpose:'loyalty',headerType:'NONE',...({reward:{title:'مكافأة ولاء',name:'loyalty_reward',body:'مرحبًا {{1}}، مكافأتك جاهزة في {{2}}. يسعدنا استقبال زيارتك!',samples:['أحمد','اسم النشاط']},offer:{title:'عرض خاص',name:'special_offer',purpose:'general',headerType:'TEXT',header:'عرض خاص لك',body:'اكتشف عرضنا الجديد، تفاصيله عبر الرابط أدناه.',footer:'العرض وفق الشروط المعلنة',buttons:[{type:'URL',text:'تفاصيل العرض',url:'https://rg3h.cc/'}]},reminder:{title:'تذكير بزيارة',name:'visit_reminder',body:'مرحبًا {{1}}، اشتقنا لزيارتك! اكتشف جديدنا في {{2}}.',samples:['أحمد','اسم النشاط']}})[id]};}};
})();
